public class Driver { static class Counter{private int count; synchronized void increment(){count++;}synchronized int value(){return count;}}public static void main(String[]a)throws InterruptedException{Counter c=new Counter();Thread[] workers=new Thread[10];for(int i=0;i<workers.length;i++){workers[i]=new Thread(()->{for(int j=0;j<1000;j++)c.increment();});workers[i].start();}for(Thread t:workers)t.join();System.out.println("Expected Count: 10000");System.out.println("Synchronized Count: "+c.value());}}
